import fs from 'fs';

const path = 'src/App.jsx';
let app = fs.readFileSync(path, 'utf8');
const start = app.indexOf('const TIPS_DATA = [');
if (start < 0) throw new Error('TIPS_DATA not found');
const end = app.indexOf('\n];', start);
if (end < 0) throw new Error('TIPS_DATA closing bracket not found');
const block = app.slice(start, end);

const categories = ['dog','cat','health','life','food','training','safety','grooming'];
const ids = [...block.matchAll(/id:\s*"t(\d+)"/g)].map(m => Number(m[1]));
const cats = [...block.matchAll(/category:\s*"(dog|cat|health|life|food|training|safety|grooming)"/g)].map(m => m[1]);
const titles = new Set([...block.matchAll(/title:\s*\{\s*ko:\s*"([^"]+)"/g)].map(m => m[1]));
const counts = Object.fromEntries(categories.map(c => [c, cats.filter(x => x === c).length]));
if (!ids.length || categories.some(c => !counts[c])) throw new Error(`Invalid PetInfo inventory: ${JSON.stringify(counts)}`);
const maxId = Math.max(...ids);
if (maxId < 290) throw new Error(`Expected dataset through at least t290, found t${maxId}.`);

const candidates = [
  {category:'dog',featured:true,titleKo:'산책 뒤 발가락 사이도 짧게 확인해요',titleEn:'Check between the toes after walks',summaryKo:'모래나 작은 이물질이 끼지 않았는지 발바닥과 발가락 사이를 살펴요.',summaryEn:'Look over paw pads and between the toes for grit or small debris after walks.',bodyKo:'산책 후 발을 닦을 때 발가락 사이와 패드 주변을 함께 확인하세요. 작은 돌이나 가시가 보이면 무리하게 깊이 파지 말고, 절뚝거림이나 붓기·출혈이 있으면 동물병원에 상담하세요.',bodyEn:'When cleaning paws after a walk, check between the toes and around the pads. Avoid digging at deeply embedded objects, and seek veterinary advice for limping, swelling, or bleeding.'},
  {category:'dog',featured:false,titleKo:'엘리베이터에서는 리드줄을 짧게 잡아 안전거리를 만들어요',titleEn:'Keep the leash short in elevators',summaryKo:'문이 열리고 닫힐 때 리드줄이 문틈에 끼지 않도록 가까이에서 관리해요.',summaryEn:'Keep your dog close so the leash cannot get caught as elevator doors open or close.',bodyKo:'엘리베이터를 타기 전 반려견을 보호자 가까이에 두고 리드줄이 길게 늘어지지 않게 잡으세요. 문이 열릴 때 다른 사람이나 동물이 있는지 먼저 확인하고 천천히 이동하세요.',bodyEn:'Keep your dog close before entering an elevator and avoid slack leash near the doors. Check for people or animals before exiting and move calmly.'},
  {category:'cat',featured:true,titleKo:'고양이 장난감 끈은 놀이가 끝나면 치워둬요',titleEn:'Put string toys away after play',summaryKo:'낚싯대 줄이나 실 같은 긴 끈은 보호자와 놀 때만 사용하고 보관해요.',summaryEn:'Use wand strings and similar long cords only during supervised play and store them afterward.',bodyKo:'긴 실과 끈, 리본은 삼키면 위험할 수 있어 놀이가 끝나면 닿지 않는 곳에 보관하세요. 삼켰을 가능성이 있거나 입·항문에서 끈이 보이면 당기지 말고 즉시 동물병원에 연락하세요.',bodyEn:'Long strings, ribbons, and cords can be dangerous if swallowed. Store them out of reach after play, and if ingestion is suspected or string is visible from the mouth or rectum, do not pull it—contact a veterinarian promptly.'},
  {category:'cat',featured:false,titleKo:'고양이 식사 공간은 지나가는 동선에서 조금 비켜둬요',titleEn:'Place cat feeding areas away from busy walkways',summaryKo:'사람이 자주 오가는 통로보다 조용하고 안정적인 위치가 식사에 편해요.',summaryEn:'A quieter feeding spot away from constant foot traffic can make meals more comfortable.',bodyKo:'식기 주변을 자주 지나가거나 큰 소음이 나는 위치는 피하고, 여러 마리가 함께 산다면 서로 거리를 두고 먹을 수 있게 식사 공간을 나눠 주세요.',bodyEn:'Avoid feeding spots with frequent foot traffic or loud noise. In multi-cat homes, separate feeding stations can reduce competition and stress.'},
  {category:'health',featured:true,titleKo:'평소 체중을 같은 조건에서 주기적으로 기록해요',titleEn:'Track body weight under consistent conditions',summaryKo:'비슷한 시간대와 같은 저울로 재면 작은 변화도 비교하기 쉬워요.',summaryEn:'Using the same scale and similar timing makes weight trends easier to compare.',bodyKo:'가능하면 같은 저울로 주기적으로 체중을 기록하고 급격한 증가나 감소가 반복되는지 살펴보세요. 식욕 변화나 처짐 등 다른 증상이 함께 있으면 수의사에게 상담하세요.',bodyEn:'Record weight periodically using the same scale when possible. Repeated or rapid changes, especially with appetite or energy changes, should be discussed with a veterinarian.'},
  {category:'health',featured:false,titleKo:'구토나 설사가 반복되면 횟수와 모습을 함께 기록해요',titleEn:'Track frequency and appearance of repeated vomiting or diarrhea',summaryKo:'몇 번 있었는지와 시간, 색·형태 같은 특징을 적어두면 진료 설명에 도움이 돼요.',summaryEn:'Note timing, frequency, and appearance to help describe symptoms accurately at a veterinary visit.',bodyKo:'증상이 반복되면 시간과 횟수, 먹은 음식, 물 섭취, 대변이나 구토물의 특징을 기록하세요. 혈액이 보이거나 심한 무기력, 탈수, 반복 구토가 있으면 기록을 더 모으기보다 신속히 진료받으세요.',bodyEn:'If symptoms repeat, note the time, frequency, recent food, water intake, and appearance. Blood, marked lethargy, dehydration, or repeated vomiting warrants prompt veterinary care.'},
  {category:'life',featured:true,titleKo:'여행이나 외출 전에는 평소 루틴을 크게 바꾸지 않아요',titleEn:'Keep routines steady before travel or long outings',summaryKo:'출발 직전 식사·산책·휴식 시간을 크게 바꾸기보다 익숙한 흐름을 유지해요.',summaryEn:'Keeping familiar meal, walk, and rest patterns can make travel days less disruptive.',bodyKo:'이동이 예정된 날에도 가능한 범위에서 평소 식사와 배변, 휴식 시간을 유지하세요. 이동장이나 차량은 미리 익숙하게 해두고 출발 직전에 과도하게 먹이는 것은 피하세요.',bodyEn:'On travel days, keep meals, toileting, and rest as familiar as practical. Acclimate pets to carriers or vehicles in advance and avoid unusually large meals immediately before departure.'},
  {category:'life',featured:false,titleKo:'반려동물 침구는 완전히 말린 뒤 다시 사용해요',titleEn:'Dry pet bedding fully before reuse',summaryKo:'세탁한 방석과 담요가 눅눅하지 않도록 충분히 건조해요.',summaryEn:'Make sure washed beds and blankets are completely dry before returning them to use.',bodyKo:'세탁 후 속까지 마르지 않은 침구는 냄새와 습기가 남을 수 있어 충분히 건조하세요. 세탁 제품은 반려동물용품에 적합한지 확인하고 향이 지나치게 강한 제품은 피하는 것이 좋아요.',bodyEn:'Bedding that remains damp inside can retain moisture and odor. Dry it thoroughly and use cleaning products appropriate for pet items, avoiding overly strong fragrances.'},
  {category:'food',featured:true,titleKo:'간식도 하루 총 급여량에 포함해 생각해요',titleEn:'Count treats as part of the daily food total',summaryKo:'간식이 많아지면 주식 급여량과 전체 열량 균형이 달라질 수 있어요.',summaryEn:'Treats can meaningfully affect total daily calories and portion balance.',bodyKo:'훈련이나 놀이 중 주는 간식도 하루 섭취량에 포함해 관리하세요. 체중 조절이 필요하거나 치료식을 먹는 경우에는 적절한 간식 종류와 양을 담당 수의사와 상의하세요.',bodyEn:'Include training and play treats in the daily intake. For pets needing weight control or therapeutic diets, discuss suitable treat types and amounts with the veterinary team.'},
  {category:'food',featured:false,titleKo:'사료 봉투를 새로 열면 개봉 날짜를 적어둬요',titleEn:'Mark the opening date on new food bags',summaryKo:'개봉 시점을 적어두면 보관 기간과 신선도를 관리하기 쉬워요.',summaryEn:'Writing down the opening date makes storage time and freshness easier to track.',bodyKo:'사료는 원래 포장에 넣은 채 밀폐 용기에 보관하면 제품 정보와 유통기한을 함께 확인하기 쉽습니다. 냄새나 색, 질감이 평소와 다르면 급여하지 마세요.',bodyEn:'Keeping food in its original bag inside a sealed container preserves product information and expiry details. Do not feed food with unusual odor, color, or texture.'},
  {category:'training',featured:true,titleKo:'새로운 신호는 조용한 공간에서 먼저 연습해요',titleEn:'Teach new cues in a quiet environment first',summaryKo:'방해 자극이 적은 곳에서 성공 경험을 만든 뒤 조금씩 장소를 넓혀요.',summaryEn:'Start with few distractions, then gradually practice in more challenging environments.',bodyKo:'처음부터 산책길처럼 자극이 많은 곳에서 연습하기보다 집 안의 조용한 공간에서 짧게 반복하세요. 성공률이 올라가면 거리와 소음, 주변 자극을 조금씩 늘려 주세요.',bodyEn:'Rather than starting in a highly distracting place, practice briefly in a quiet room. Once the behavior is reliable, gradually add distance, noise, and other distractions.'},
  {category:'training',featured:false,titleKo:'반려동물이 흥분했을 때는 쉬운 행동부터 요청해요',titleEn:'Ask for an easy behavior when your pet is excited',summaryKo:'어려운 훈련을 강요하기보다 이미 잘 아는 간단한 행동으로 집중을 되찾아요.',summaryEn:'When excitement is high, use a familiar easy cue instead of demanding a difficult task.',bodyKo:'흥분이 큰 상황에서는 앉아, 보기처럼 익숙한 행동 하나를 짧게 요청하고 성공하면 바로 보상하세요. 반응이 어렵다면 거리를 늘리거나 자극에서 벗어나 진정할 시간을 주세요.',bodyEn:'In exciting situations, ask for one familiar behavior such as sit or eye contact and reward success promptly. If your pet cannot respond, increase distance from the trigger and allow time to settle.'},
  {category:'safety',featured:true,titleKo:'자동문과 에스컬레이터 주변에서는 발과 리드줄을 더 주의해요',titleEn:'Use extra caution around automatic doors and escalators',summaryKo:'작은 발과 긴 털, 리드줄이 움직이는 장치에 끼지 않도록 가까이에서 관리해요.',summaryEn:'Keep paws, long fur, and leashes clear of moving mechanisms around automatic doors and escalators.',bodyKo:'가능하면 에스컬레이터 대신 엘리베이터를 이용하고, 자동문 근처에서는 반려동물을 보호자 가까이에 두세요. 이동 장치에 발이나 털이 끼는 사고가 발생하면 즉시 안전한 곳으로 이동해 상태를 확인하세요.',bodyEn:'Use elevators instead of escalators when practical and keep pets close around automatic doors. If a paw or fur is caught in moving equipment, move to safety and assess for injury promptly.'},
  {category:'safety',featured:false,titleKo:'청소용 세제는 사용 중에도 반려동물 접근을 막아요',titleEn:'Keep pets away from cleaning products while in use',summaryKo:'보관할 때뿐 아니라 바닥이나 욕실을 청소하는 동안에도 접근을 제한해요.',summaryEn:'Restrict access not only during storage but also while cleaners are being used on floors or surfaces.',bodyKo:'세제가 마르거나 충분히 헹궈질 때까지 반려동물이 닿지 않게 하고 제품 라벨의 사용법을 따르세요. 핥았거나 눈·피부에 닿은 뒤 이상 반응이 보이면 제품 정보를 준비해 동물병원에 문의하세요.',bodyEn:'Keep pets away until treated surfaces are dry or properly rinsed, following label directions. If exposure occurs and symptoms appear, have the product information ready when contacting a veterinarian.'},
  {category:'grooming',featured:true,titleKo:'발톱은 한 번에 많이 자르기보다 조금씩 관리해요',titleEn:'Trim nails in small amounts rather than all at once',summaryKo:'혈관이 가까운 발톱은 조금씩 자르며 길이를 관리하는 편이 안전해요.',summaryEn:'Small, regular trims are safer when the quick is close to the nail tip.',bodyKo:'발톱 끝을 조금씩 잘라 혈관 부위를 피하고, 어두운 발톱처럼 위치가 잘 보이지 않으면 무리하지 마세요. 출혈이 멈추지 않거나 발톱이 갈라졌다면 동물병원에 상담하세요.',bodyEn:'Trim only small amounts from the tip and avoid the quick. If the quick is hard to see, do not force a large trim. Persistent bleeding or a split nail should be assessed by a veterinarian.'},
  {category:'grooming',featured:false,titleKo:'눈 주변을 닦을 때는 한쪽마다 깨끗한 거즈를 사용해요',titleEn:'Use clean gauze for each eye area',summaryKo:'눈 주변 분비물을 닦을 때 한쪽에서 사용한 거즈를 반대쪽에 그대로 쓰지 않아요.',summaryEn:'When wiping discharge, use a fresh piece of gauze for each eye area.',bodyKo:'미지근한 물로 적신 부드러운 거즈로 눈 바깥 주변만 가볍게 닦고 눈 안을 문지르지 마세요. 충혈, 통증, 심한 눈곱, 눈을 뜨기 어려워하는 모습이 지속되면 진료가 필요합니다.',bodyEn:'Use soft gauze dampened with lukewarm water around the outside of the eye and avoid rubbing the eye itself. Persistent redness, pain, heavy discharge, or difficulty opening the eye warrants veterinary care.'}
];

const fresh = candidates.filter(item => !titles.has(item.titleKo));
if (fresh.length !== candidates.length) {
  const dupes = candidates.filter(item => titles.has(item.titleKo)).map(item => item.titleKo);
  throw new Error(`Duplicate PetInfo titles detected: ${dupes.join(', ')}`);
}
if (fresh.length !== 16) throw new Error(`Expected 16 fresh PetInfo items, got ${fresh.length}`);

let nextId = maxId + 1;
const sourceDate = '2026-08-25';
const esc = s => String(s).replace(/\\/g,'\\\\').replace(/"/g,'\\"');
const lines = fresh.map(item => `\n  { id: "t${nextId++}", category: "${item.category}", featured: ${item.featured},\n    title: { ko: "${esc(item.titleKo)}", en: "${esc(item.titleEn)}" },\n    summary: { ko: "${esc(item.summaryKo)}", en: "${esc(item.summaryEn)}" },\n    body: { ko: "${esc(item.bodyKo)}", en: "${esc(item.bodyEn)}" }, sourceDate: "${sourceDate}" },`).join('');

app = app.slice(0, end) + lines + app.slice(end);
fs.writeFileSync(path, app);
console.log(`Added ${fresh.length} PetInfo items through t${nextId - 1}`);
